// RFC 9001 A.1 and RFC 9369 A.1, not values generated by this decoder.
func TestRFCInitialKeyVectors(t *testing.T) {
	dcid, _ := hex.DecodeString("8394c8f03e515708")
	for _, tc := range []struct {
		version uint32
		key, iv string
	}{
		{1, "1f369613dd76d5467730efcbe3b1a22d", "fa044b2f42a3fd3b46fb255c"},
		{0x6b3343cf, "8b1a0bc121284290a29e0971b5cd045d", "91f73e2351d8fa91660e909f"},
	} {
		key, iv, _, err := initialKeys(tc.version, dcid)
		if err != nil || hex.EncodeToString(key) != tc.key || hex.EncodeToString(iv) != tc.iv {
			t.Fatal("RFC Initial keys differ", err)
		}
	}
}

func TestObserverReadsRealQUICGoInitialWithoutProfileSecrets(t *testing.T) {
	for _, format := range []int{3, 4} {
		for _, version := range []quic.Version{quic.Version1, quic.Version2} {
			t.Run(fmt.Sprintf("%s/wire%d", version, format), func(t *testing.T) {
				sink, err := net.ListenPacket("udp", "127.0.0.1:0")
				if err != nil {
					t.Fatal(err)
				}
				defer sink.Close()
				clientSocket, err := net.ListenPacket("udp", "127.0.0.1:0")
				if err != nil {
					t.Fatal(err)
				}
				var token quicadmission.Token
				_, _ = rand.Read(token[:])
				pool, err := quicadmission.NewCIDPool([]quicadmission.Token{token})
				if err != nil {
					t.Fatal(err)
				}
				var generator quic.ConnectionIDGenerator = pool
				if format == 4 {
					generator = &quicadmission.ZeroCIDGenerator{}
				}
				transport := &quic.Transport{Conn: clientSocket, ConnectionIDGenerator: generator}
				defer transport.Close()
				ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
				defer cancel()
				done := make(chan error, 1)
				go func() {
					config := quicpeer.ClientConfig()
					config.Versions = []quic.Version{version}
					tlsConfig := &tls.Config{ServerName: "observer.invalid", NextProtos: []string{"h3"}}
					quicpeer.ConfigureTLSPrivacy(tlsConfig, format)
					_, err := transport.Dial(ctx, sink.LocalAddr(), tlsConfig, config)
					done <- err
				}()
				defer func() {
					cancel()
					transport.Close()
					select {
					case <-done:
					case <-time.After(time.Second):
						t.Error("capture dial leaked")
					}
				}()
				_ = sink.SetReadDeadline(time.Now().Add(2 * time.Second))
				var observer Observer
				var summary Summary
				for i := 0; i < 16; i++ {
					packet := make([]byte, 65535)
					n, _, err := sink.ReadFrom(packet)
					if err != nil {
						t.Fatal(err)
					}
					original := append([]byte(nil), packet[:n]...)
					summary, err = observer.Observe(packet[:n])
					if !bytes.Equal(packet[:n], original) {
						t.Fatal("observer modified datagram")
					}
					if err == nil {
						break
					}
					if !errors.Is(err, ErrIncomplete) {
						t.Fatal("could not decode real Initial", err)
					}
				}
				expectedSCID := 20
				if format == 4 {
					expectedSCID = 0
					wantGroups := []uint16{4588, 29, 23, 24}
					if !reflect.DeepEqual(summary.ClientHello.SupportedGroups, wantGroups) {
						t.Fatal("wire4 curve preferences differ from configured baseline")
					}
				}
				if summary.Version != uint32(version) || summary.SCIDLength != expectedSCID || summary.ClientHello.SessionIDSize != 0 || len(summary.ClientHello.TransportParameters) == 0 || len(summary.ClientHello.ALPN) != 1 || summary.ClientHello.ALPN[0] != "h3" {
					t.Fatalf("incomplete public metadata: %+v", summary)
				}
				limits := map[uint64]uint64{4: 16 * 1024 * 1024, 5: 8 * 1024 * 1024, 6: 8 * 1024 * 1024, 7: 8 * 1024 * 1024}
				for _, parameter := range summary.ClientHello.TransportParameters {
					if want, ok := limits[parameter.ID]; ok {
						if parameter.Integer == nil || *parameter.Integer != want {
							t.Fatalf("production transport parameter %d differs", parameter.ID)
						}
						delete(limits, parameter.ID)
					}
				}
				if len(limits) != 0 {
					t.Fatal("production transport limits missing")
				}
				encoded, err := json.Marshal(summary)
				if err != nil {
					t.Fatal(err)
				}
				if bytes.Contains(encoded, []byte(hex.EncodeToString(token[:]))) || bytes.Contains(encoded, []byte("observer.invalid")) {
					t.Fatal("summary exports raw connection identity or SNI")
				}
				t.Log(string(encoded))
				if output := os.Getenv("ATLANT_QUIC_BASELINE_OUTPUT"); output != "" && version == quic.Version1 && format == 3 {
					if !filepath.IsAbs(output) || filepath.Base(output) != "atlant-initial.json" {
						t.Fatal("expected an absolute atlant-initial.json artifact path")
					}
					if err := os.WriteFile(output, append(encoded, '\n'), 0600); err != nil {
						t.Fatal(err)
					}
				}
			})
		}
	}
}

func TestObserverRejectsConflictingAndOversizedCrypto(t *testing.T) {
	var observer Observer
	if err := observer.frames([]byte{6, 0, 1, 1}); err != nil {
		t.Fatal(err)
	}
	if err := observer.frames([]byte{6, 0, 1, 2}); err == nil {
		t.Fatal("conflicting CRYPTO accepted")
	}
	if err := observer.frames([]byte{6, 0x80, 1, 0, 0, 1, 1}); err == nil {
		t.Fatal("oversized CRYPTO offset accepted")
	}
	if err := observer.frames([]byte{2, 0, 0, 0x41, 0x01, 0}); err == nil {
		t.Fatal("oversized ACK ranges accepted")
	}
}

func FuzzObserveInitial(f *testing.F) {
	f.Add([]byte{0xc0, 0, 0, 0, 1, 8})
	f.Add(auditInitial([]byte{6, 0, 4, 1, 0, 0, 0}, 0, []byte{1, 2}))
	f.Fuzz(func(t *testing.T, data []byte) {
		if len(data) > 65535 {
			t.Skip()
		}
		var observer Observer
		_, _ = observer.Observe(data)
	})
}

// This fixture exercises packet protection and fragmented CRYPTO independently
// of the real-client captures above. Initial keys are public, not profile keys.
func auditInitial(frames []byte, pn uint16, scid []byte) []byte {
	dcid := []byte{1, 2, 3, 4, 5, 6, 7, 8}
	header := []byte{0xc1, 0, 0, 0, 1, byte(len(dcid))}
	header = append(header, dcid...)
	header = append(header, byte(len(scid)))
	header = append(header, scid...)
	header = append(header, 0) // Empty Retry token.
	plain := make([]byte, 1200-len(header)-2-2-16)
	copy(plain, frames)
	length := 2 + len(plain) + 16
	header = append(header, 0x40|byte(length>>8), byte(length))
	pnOffset := len(header)
	header = binary.BigEndian.AppendUint16(header, pn)
	key, iv, hp, _ := initialKeys(1, dcid)
	iv[10] ^= byte(pn >> 8)
	iv[11] ^= byte(pn)
	block, _ := aes.NewCipher(key)
	aead, _ := cipher.NewGCM(block)
	packet := aead.Seal(append([]byte(nil), header...), iv, plain, header)
	protection, _ := aes.NewCipher(hp)
	var mask [16]byte
	protection.Encrypt(mask[:], packet[pnOffset+4:pnOffset+20])
	packet[0] ^= mask[0] & 15
	packet[pnOffset] ^= mask[1]
	packet[pnOffset+1] ^= mask[2]
	return packet
}

func TestObserverFragmentOrderTamperAndSCIDBinding(t *testing.T) {
	body := make([]byte, 34)
	body[0], body[1] = 3, 3
	body = append(body, 0, 0, 2, 0x13, 1, 1, 0, 0, 0)
	hello := append([]byte{1, 0, 0, byte(len(body))}, body...)
	scid := []byte{1, 2}
	first := auditInitial(append([]byte{6, 0, 24}, hello[:24]...), 0, scid)
	last := auditInitial(append([]byte{6, 24, byte(len(hello) - 24)}, hello[24:]...), 1, scid)
	var observer Observer
	if _, err := observer.Observe(last); !errors.Is(err, ErrIncomplete) {
		t.Fatal("out-of-order CRYPTO was not held", err)
	}
	foreign := auditInitial(append([]byte{6, 0, 24}, hello[:24]...), 0, []byte{3, 4})
	if _, err := observer.Observe(foreign); err == nil {
		t.Fatal("mixed different client SCIDs")
	}
	tampered := append([]byte(nil), first...)
	tampered[len(tampered)-1] ^= 1
	if _, err := observer.Observe(tampered); err == nil {
		t.Fatal("accepted invalid packet protection")
	}
	summary, err := observer.Observe(first)
	if err != nil || summary.ClientHello.HelloSize != len(hello) {
		t.Fatal("fragment reassembly failed", err)
	}
}

func FuzzInitialCryptoFrames(f *testing.F) {
	f.Add([]byte{6, 0, 4, 1, 0, 0, 0})
	f.Add([]byte{2, 1, 0, 0, 0})
	f.Add([]byte{6, 0, 1, 1, 6, 0, 1, 2})
	f.Fuzz(func(t *testing.T, data []byte) {
		if len(data) > 65535 {
			t.Skip()
		}
		var observer Observer
		_ = observer.frames(data)
	})
}
